uint32_t CMMC_ClockFor(CMMCState *s){CMMC_Activate(s);return CSDMMC_CoreClock();}
uint32_t CMMC_TickFor(CMMCState *s){
 uint32_t result=s->control[2];s->control[2]+=s->control[3];s->control[4]++;
 if(s->control[16]&&s->control[4]==s->control[16])s->h.Instance->STA=s->control[17];
 return result;
}
uint32_t CMMC_FrequencyFor(CMMCState *s,uint32_t selection){assert(selection==0x00200000U);s->control[6]++;return s->control[5];}
