void CMMC_Reset(CMMCState *s,uint32_t variant){
 memset(s,0,sizeof(*s));CSDMMC_Reset(&s->ll);s->control[0]=variant;s->control[1]=1;s->control[3]=1;s->control[5]=64000000;
 for(uint32_t i=0;i<16384;i++)((uint8_t *)s->buffers)[i]=(uint8_t)(i*37+11);
 CMMC_Activate(s);s->h.pTxBuffPtr=(uint8_t *)s->buffers[0];s->h.pRxBuffPtr=(uint8_t *)s->buffers[1];
CMMC_SetCallback(s,0,CMMC_Callback(0,1));
CMMC_SetCallback(s,1,CMMC_Callback(1,1));
CMMC_SetCallback(s,2,CMMC_Callback(2,1));
CMMC_SetCallback(s,3,CMMC_Callback(3,1));
CMMC_SetCallback(s,4,CMMC_Callback(4,1));
CMMC_SetCallback(s,5,CMMC_Callback(5,1));
CMMC_SetCallback(s,16,CMMC_Callback(16,1));
CMMC_SetCallback(s,17,CMMC_Callback(17,1));
}
uint32_t CMMC_Compare(CMMCState *a,CMMCState *b){const uint32_t counts[]={66,156,64,16,384,1024,16384,3,24,1024,7,37,10,128,16,0,2,4096,1024};for(uint32_t g=0;g<19;g++)for(uint32_t i=0;i<counts[g];i++)if(CMMC_Get(a,g,i)!=CMMC_Get(b,g,i))return ((g+1)<<16)|i;
for(uint32_t i=0;i<2;i++)if(Normalize(a,CMMC_GetPointer(a,i))!=Normalize(b,CMMC_GetPointer(b,i)))return 0x400000|i;
if(CMMC_GetCallback(a,0)!=CMMC_GetCallback(b,0))return 0x410000|0;
if(CMMC_GetCallback(a,1)!=CMMC_GetCallback(b,1))return 0x410000|1;
if(CMMC_GetCallback(a,2)!=CMMC_GetCallback(b,2))return 0x410000|2;
if(CMMC_GetCallback(a,3)!=CMMC_GetCallback(b,3))return 0x410000|3;
if(CMMC_GetCallback(a,4)!=CMMC_GetCallback(b,4))return 0x410000|4;
if(CMMC_GetCallback(a,5)!=CMMC_GetCallback(b,5))return 0x410000|5;
if(CMMC_GetCallback(a,16)!=CMMC_GetCallback(b,16))return 0x410000|16;
if(CMMC_GetCallback(a,17)!=CMMC_GetCallback(b,17))return 0x410000|17;
return 0;}
